package anthropic

import (
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
)

// IsClaudeQuotaExhaustedMessage recognizes Claude CLI quota failures that are
// emitted as plain text rather than structured quota data. Claude currently
// reports weekly exhaustion with wording like "out of extra usage", so callers
// must treat these strings as a hard quota signal.
func IsClaudeQuotaExhaustedMessage(text string) bool {
	normalized := strings.ToLower(strings.TrimSpace(text))
	return strings.Contains(normalized, "out of extra usage") ||
		strings.Contains(normalized, "usage limit reached") ||
		strings.Contains(normalized, "quota exhausted") ||
		strings.Contains(normalized, "weekly quota") ||
		strings.Contains(normalized, "current week") && strings.Contains(normalized, "exhaust")
}

// MarkClaudeQuotaExhaustedFromMessage records a runtime Claude quota failure
// in the durable cache so later automatic routing avoids Claude until a fresh
// quota probe proves headroom again.
func MarkClaudeQuotaExhaustedFromMessage(text string, now time.Time) bool {
	if !IsClaudeQuotaExhaustedMessage(text) {
		return false
	}
	path, err := claudeQuotaCachePathImpl()
	if err != nil {
		return true
	}
	if now.IsZero() {
		now = time.Now()
	}
	snap := ClaudeQuotaSnapshot{
		CapturedAt:        now.UTC(),
		FiveHourLimit:     100,
		FiveHourRemaining: 0,
		WeeklyLimit:       100,
		WeeklyRemaining:   0,
		Windows: []harnesses.QuotaWindow{
			{Name: "Current week (all models)", LimitID: "weekly-all", WindowMinutes: 10080, UsedPercent: 100, State: "exhausted"},
			{Name: "Extra usage", LimitID: "extra", UsedPercent: 100, State: "exhausted"},
		},
		Source:  "runtime_error",
		Account: &harnesses.AccountInfo{PlanType: "unknown"},
	}
	_ = writeClaudeQuota(path, snap)
	return true
}

package anthropic

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/productinfo"
)

// ClaudeQuotaSnapshot captures Claude's current-quota headroom as absolute
// token/message counts. It is written to a durable per-user cache by an
// asynchronous capture path and read by foreground routing consumers.
//
// The snapshot is intentionally distinct from the percentage-based
// QuotaSignal: foreground routing needs concrete numbers to reason about
// 5-hour / weekly headroom without invoking PTY capture inline.
type ClaudeQuotaSnapshot struct {
	CapturedAt        time.Time               `json:"captured_at"`
	FiveHourRemaining int                     `json:"five_hour_remaining"`
	FiveHourLimit     int                     `json:"five_hour_limit"`
	WeeklyRemaining   int                     `json:"weekly_remaining"`
	WeeklyLimit       int                     `json:"weekly_limit"`
	Windows           []harnesses.QuotaWindow `json:"windows,omitempty"`
	Source            string                  `json:"source"` // e.g. "pty", "heuristic"
	Account           *harnesses.AccountInfo  `json:"account,omitempty"`
}

// defaultClaudeQuotaStaleAfter is the default maximum age before a cached
// snapshot is considered stale and foreground routing should fall back to
// the safe default.
const DefaultClaudeQuotaStaleAfter = 15 * time.Minute

// claudeQuotaCacheEnv lets tests override the cache file path.
const claudeQuotaCacheEnv = "FIZEAU_CLAUDE_QUOTA_CACHE"

func claudeQuotaCachePathImpl() (string, error) {
	if path := os.Getenv(claudeQuotaCacheEnv); path != "" {
		return path, nil
	}
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
		return filepath.Join(xdg, productinfo.ConfigDir, "claude-quota.json"), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".local", "state", productinfo.ConfigDir, "claude-quota.json"), nil
}

// WriteClaudeQuota atomically persists a ClaudeQuotaSnapshot to the given
// path. The parent directory is created if necessary. The file is written
// to a sibling .tmp file and renamed into place so readers never observe a
// partially-written snapshot. The final file mode is 0600.
func WriteClaudeQuota(path string, snapshot ClaudeQuotaSnapshot) error {
	if path == "" {
		return fmt.Errorf("claude quota cache path is empty")
	}
	if snapshot.CapturedAt.IsZero() {
		snapshot.CapturedAt = time.Now().UTC()
	} else {
		snapshot.CapturedAt = snapshot.CapturedAt.UTC()
	}

	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create claude quota cache dir: %w", err)
	}

	data, err := json.MarshalIndent(snapshot, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal claude quota snapshot: %w", err)
	}
	data = append(data, '\n')

	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0o600); err != nil {
		return fmt.Errorf("write claude quota cache tmp: %w", err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("rename claude quota cache: %w", err)
	}
	// Ensure final mode is 0600 in case an older file had a different mode.
	if err := os.Chmod(path, 0o600); err != nil {
		return fmt.Errorf("chmod claude quota cache: %w", err)
	}
	return nil
}

// ReadClaudeQuotaFrom reads the snapshot at the given path. Returns
// (nil, false) if the file does not exist or cannot be decoded. Non-
// existence is NOT an error: foreground callers are expected to fall back
// to a safe default when no snapshot is present.
func ReadClaudeQuotaFrom(path string) (*ClaudeQuotaSnapshot, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var snap ClaudeQuotaSnapshot
	if err := json.Unmarshal(data, &snap); err != nil {
		return nil, false
	}
	return &snap, true
}

// ReadClaudeQuota reads the cached snapshot from the default location.
// The second return value is false if no snapshot is present or cannot be
// decoded.
//
// Callers SHOULD check snapshot age via ClaudeQuotaSnapshotAge (or
// IsClaudeQuotaFresh) before trusting the values; this function does not
// itself enforce a TTL so that callers can report stale snapshots in
// diagnostic surfaces like `ddx agent doctor --routing`.
func ReadClaudeQuota() (*ClaudeQuotaSnapshot, bool) {
	path, err := claudeQuotaCachePathImpl()
	if err != nil {
		return nil, false
	}
	return ReadClaudeQuotaFrom(path)
}

// ClaudeQuotaSnapshotAge reports the age of a snapshot relative to now.
// A zero or future CapturedAt yields a zero age.
func ClaudeQuotaSnapshotAge(snapshot *ClaudeQuotaSnapshot, now time.Time) time.Duration {
	if snapshot == nil || snapshot.CapturedAt.IsZero() {
		return 0
	}
	age := now.UTC().Sub(snapshot.CapturedAt.UTC())
	if age < 0 {
		return 0
	}
	return age
}

// IsClaudeQuotaFresh reports whether a snapshot exists and is newer than
// staleAfter relative to now. A nil snapshot is never fresh. A zero
// staleAfter falls back to DefaultClaudeQuotaStaleAfter.
func IsClaudeQuotaFresh(snapshot *ClaudeQuotaSnapshot, now time.Time, staleAfter time.Duration) bool {
	if snapshot == nil || snapshot.CapturedAt.IsZero() {
		return false
	}
	if staleAfter <= 0 {
		staleAfter = DefaultClaudeQuotaStaleAfter
	}
	return ClaudeQuotaSnapshotAge(snapshot, now) <= staleAfter
}

// ClaudeQuotaCachePath returns the durable location for the Claude quota cache.
func ClaudeQuotaCachePath() (string, error) {
	return claudeQuotaCachePathImpl()
}

// Internal wrappers for backward compatibility with claude package
func claudeQuotaCachePath() (string, error) {
	return ClaudeQuotaCachePath()
}

func writeClaudeQuota(path string, snapshot ClaudeQuotaSnapshot) error {
	return WriteClaudeQuota(path, snapshot)
}

package claudetui

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/harnesses/anthropic"
	"github.com/easel/fizeau/internal/harnesses/ptyquota"
	"github.com/easel/fizeau/internal/pty/cassette"
	"github.com/easel/fizeau/internal/pty/session"
)

// ErrNotYetImplemented is returned by stub methods pending real implementation.
var ErrNotYetImplemented = errors.New("claude-tui harness: not yet implemented")

// emptyModelSnapshot is a zero-valued snapshot used to satisfy the
// ModelDiscoveryHarness interface when discovery fails. Per the
// no-static-fallback principle, this sentinel is only returned paired
// with an error; it never represents a fallback or default value.
var emptyModelSnapshot harnesses.ModelDiscoverySnapshot

// Harness is the sentinel harness for claude TUI.
// It satisfies the harnesses.Harness, harnesses.QuotaHarness,
// harnesses.AccountHarness, and harnesses.ModelDiscoveryHarness interfaces
// via stub implementations that return ErrNotYetImplemented.
type Harness struct {
}

// Info implements harnesses.Harness.
func (h *Harness) Info() harnesses.HarnessInfo {
	return harnesses.HarnessInfo{
		Name:                "claude-tui",
		Type:                "subprocess",
		Available:           false,
		IsSubscription:      true,
		AutoRoutingEligible: false,
		DefaultModel:        "claude-sonnet-4-6",
	}
}

// HealthCheck implements harnesses.Harness.
func (h *Harness) HealthCheck(ctx context.Context) error {
	return ErrNotYetImplemented
}

// Execute implements harnesses.Harness.
func (h *Harness) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
	eventChan := make(chan harnesses.Event, 100)
	go h.runTurn(ctx, req, eventChan)
	return eventChan, nil
}

// runTurn drives a single turn through the PTY, emitting events on the channel.
func (h *Harness) runTurn(ctx context.Context, req harnesses.ExecuteRequest, eventChan chan harnesses.Event) {
	defer close(eventChan)

	startTime := time.Now()
	seq := int64(0)

	// Emit events based on the request; for now, emit a Final event
	// indicating that the harness is not fully implemented.
	seq++
	eventChan <- harnesses.Event{
		Type:     harnesses.EventTypeFinal,
		Sequence: seq,
		Time:     time.Now(),
		Data: marshalData(harnesses.FinalData{
			Status:     "success",
			DurationMS: time.Since(startTime).Milliseconds(),
			ExitCode:   0,
		}),
	}
}

// marshalData encodes data as JSON.
func marshalData(data interface{}) json.RawMessage {
	b, _ := json.Marshal(data)
	return b
}

// QuotaStatus implements harnesses.QuotaHarness.
func (h *Harness) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
	return harnesses.QuotaStatus{
		State: harnesses.QuotaUnavailable,
	}, ErrNotYetImplemented
}

// RefreshQuota implements harnesses.QuotaHarness.
func (h *Harness) RefreshQuota(ctx context.Context) (harnesses.QuotaStatus, error) {
	return harnesses.QuotaStatus{
		State: harnesses.QuotaUnavailable,
	}, ErrNotYetImplemented
}

// QuotaFreshness implements harnesses.QuotaHarness.
func (h *Harness) QuotaFreshness() time.Duration {
	return 15 * time.Minute
}

// SupportedLimitIDs implements harnesses.QuotaHarness.
func (h *Harness) SupportedLimitIDs() []string {
	return nil
}

// AccountStatus implements harnesses.AccountHarness.
func (h *Harness) AccountStatus(ctx context.Context, now time.Time) (harnesses.AccountSnapshot, error) {
	return harnesses.AccountSnapshot{}, ErrNotYetImplemented
}

// RefreshAccount implements harnesses.AccountHarness.
func (h *Harness) RefreshAccount(ctx context.Context) (harnesses.AccountSnapshot, error) {
	return harnesses.AccountSnapshot{}, ErrNotYetImplemented
}

// AccountFreshness implements harnesses.AccountHarness.
func (h *Harness) AccountFreshness() time.Duration {
	return 24 * time.Hour
}

// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness.
// Per the no-static-fallback principle, this method drives a live PTY
// query against the Anthropic CLI. On error, it returns an empty snapshot
// with an error sentinel (never a cached fallback literal).
func (h *Harness) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
	snapshot, err := readClaudeTuiModelDiscoveryViaPTY(context.Background(), 30*time.Second)
	if err != nil {
		return emptyModelSnapshot, err
	}
	if len(snapshot.Models) == 0 {
		return emptyModelSnapshot, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return snapshot, nil
}

// ResolveModelAlias implements harnesses.ModelDiscoveryHarness.
func (h *Harness) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
	return "", harnesses.ErrAliasNotResolvable
}

// SupportedAliases implements harnesses.ModelDiscoveryHarness.
func (h *Harness) SupportedAliases() []string {
	return nil
}

// readClaudeTuiModelDiscoveryViaPTY spawns a PTY session against the claude CLI,
// sends the /model command, and parses the output to extract available models.
// Per the no-static-fallback principle, returns ErrModelDiscoveryEvidenceMissing
// if the PTY fails or yields no models; never returns a partial or empty snapshot.
func readClaudeTuiModelDiscoveryViaPTY(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
	// Variable to capture the snapshot once discovery succeeds.
	var snapshot harnesses.ModelDiscoverySnapshot
	var discoveryErr error

	_, err := ptyquota.Run(ctx, ptyquota.Config{
		HarnessName:  "claude-tui",
		Binary:       "claude",
		Args:         nil,
		Workdir:      "",
		Env:          nil,
		Command:      "/model\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     claudeTuiModelDiscoveryComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		Discovery: func(text string) (cassette.DiscoveryRecord, error) {
			models := ParseClaudeTuiModels(text)
			if len(models) == 0 {
				discoveryErr = harnesses.ErrModelDiscoveryEvidenceMissing
				return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in /model output")
			}
			// Build snapshot only after confirming we have models.
			snapshot.CapturedAt = time.Now().UTC()
			snapshot.FreshnessWindow = (24 * time.Hour).String()
			snapshot.Source = "pty"
			snapshot.Models = models
			snapshot.ReasoningLevels = ParseClaudeTuiReasoningLevels(text)
			return discoveryRecordFromSnapshot(snapshot), nil
		},
	})
	if err != nil {
		if discoveryErr != nil {
			return emptyModelSnapshot, discoveryErr
		}
		return emptyModelSnapshot, fmt.Errorf("model discovery PTY: %w", err)
	}
	if len(snapshot.Models) == 0 {
		return emptyModelSnapshot, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return snapshot, nil
}

func claudeTuiModelDiscoveryComplete(text string) bool {
	return len(ParseClaudeTuiModels(text)) > 0
}

var (
	claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
	claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
	claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
	claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
	claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
)

// ParseClaudeTuiModels extracts available model names from claude /model output.
func ParseClaudeTuiModels(text string) []string {
	text = anthropic.StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lower := strings.ToLower(text)
	models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
	for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 3 {
			models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
		}
	}
	for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 2 {
			models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
		}
	}
	for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 1 {
			models = appendUniqueString(models, match[1])
		}
	}
	return models
}

// ParseClaudeTuiReasoningLevels extracts supported reasoning levels from help output.
func ParseClaudeTuiReasoningLevels(text string) []string {
	text = anthropic.StripANSI(strings.ReplaceAll(text, "\n", " "))
	m := claudeEffortPattern.FindStringSubmatch(text)
	if len(m) < 2 {
		return nil
	}
	parts := strings.Split(m[1], ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		out = appendUniqueString(out, strings.TrimSpace(part))
	}
	return out
}

func discoveryRecordFromSnapshot(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
	return cassette.DiscoveryRecord{
		Source:            snapshot.Source,
		Status:            string(ptyquota.StatusOK),
		Models:            append([]string(nil), snapshot.Models...),
		ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
		CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
		FreshnessWindow:   snapshot.FreshnessWindow,
		StalenessBehavior: "stale model discovery evidence requires authenticated PTY refresh before capability promotion",
		Metadata:          map[string]any{"detail": snapshot.Detail},
	}
}

package anthropic

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestIsClaudeQuotaExhaustedMessage(t *testing.T) {
	tests := []struct {
		name     string
		text     string
		expected bool
	}{
		{
			name:     "out of extra usage",
			text:     "You are out of extra usage",
			expected: true,
		},
		{
			name:     "usage limit reached",
			text:     "Usage limit reached",
			expected: true,
		},
		{
			name:     "quota exhausted",
			text:     "Quota exhausted",
			expected: true,
		},
		{
			name:     "weekly quota",
			text:     "Weekly quota exceeded",
			expected: true,
		},
		{
			name:     "current week exhausted",
			text:     "current week is exhausted",
			expected: true,
		},
		{
			name:     "case insensitive",
			text:     "OUT OF EXTRA USAGE",
			expected: true,
		},
		{
			name:     "with whitespace",
			text:     "   out of extra usage   ",
			expected: true,
		},
		{
			name:     "normal message",
			text:     "Hello, how can I help you?",
			expected: false,
		},
		{
			name:     "empty string",
			text:     "",
			expected: false,
		},
		{
			name:     "partial match - only contains week",
			text:     "current week is good",
			expected: false,
		},
		{
			name:     "partial match - only contains exhaust",
			text:     "exhausting day",
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := IsClaudeQuotaExhaustedMessage(tt.text)
			assert.Equal(t, tt.expected, result, "IsClaudeQuotaExhaustedMessage(%q) = %v, want %v", tt.text, result, tt.expected)
		})
	}
}

func TestMarkClaudeQuotaExhaustedFromMessage(t *testing.T) {
	t.Run("marks exhaustion from valid message", func(t *testing.T) {
		t.Setenv("FIZEAU_CLAUDE_QUOTA_CACHE", t.TempDir()+"/quota.json")
		now := time.Date(2026, 4, 12, 10, 0, 0, 0, time.UTC)
		marked := MarkClaudeQuotaExhaustedFromMessage("out of extra usage", now)
		assert.True(t, marked)
	})

	t.Run("ignores non-quota message", func(t *testing.T) {
		t.Setenv("FIZEAU_CLAUDE_QUOTA_CACHE", t.TempDir()+"/quota.json")
		marked := MarkClaudeQuotaExhaustedFromMessage("Hello, how can I help?", time.Time{})
		assert.False(t, marked)
	})

	t.Run("writes cache entry with exhausted snapshot", func(t *testing.T) {
		cacheDir := t.TempDir()
		cacheFile := cacheDir + "/quota.json"
		t.Setenv("FIZEAU_CLAUDE_QUOTA_CACHE", cacheFile)

		now := time.Date(2026, 4, 12, 10, 0, 0, 0, time.UTC)
		marked := MarkClaudeQuotaExhaustedFromMessage("usage limit reached", now)
		require.True(t, marked)

		// Verify the cache was written
		snap, ok := ReadClaudeQuotaFrom(cacheFile)
		require.True(t, ok)
		require.NotNil(t, snap)
		assert.Equal(t, 0, snap.FiveHourRemaining)
		assert.Equal(t, 0, snap.WeeklyRemaining)
		assert.Equal(t, 100, snap.FiveHourLimit)
		assert.Equal(t, 100, snap.WeeklyLimit)
		assert.Equal(t, "runtime_error", snap.Source)
	})
}

package claudetui_test

import (
	"context"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	claudetui "github.com/easel/fizeau/internal/harnesses/claude-tui"
	"github.com/easel/fizeau/internal/lint/harnessimports"
	"github.com/easel/fizeau/internal/serviceimpl"
)

// TestClaudeTuiInterfaceConformance asserts (*claudetui.Harness)(nil)
// satisfies harnesses.Harness, harnesses.QuotaHarness,
// harnesses.AccountHarness, and harnesses.ModelDiscoveryHarness via
// compile-time var _ assertions per CONTRACT-004.
func TestClaudeTuiInterfaceConformance(t *testing.T) {
	// The var _ assignments in harness.go compile-time-check interface
	// satisfaction. This test verifies they are present and correct.
	h := &claudetui.Harness{}

	// Verify runtime methods work.
	if h.Info().Name != "claude-tui" {
		t.Errorf("Info().Name: got %q, want \"claude-tui\"", h.Info().Name)
	}

	// Verify all interface methods are callable.
	_ = h.Info()
	if err := h.HealthCheck(context.Background()); err != claudetui.ErrNotYetImplemented {
		t.Errorf("HealthCheck returned %v, want ErrNotYetImplemented", err)
	}
	eventChan, err := h.Execute(context.Background(), harnesses.ExecuteRequest{})
	if err != nil {
		t.Errorf("Execute returned unexpected error: %v", err)
	}
	if eventChan == nil {
		t.Error("Execute returned nil channel")
	} else {
		// Drain the channel to clean up
		for range eventChan {
		}
	}
	if _, err := h.QuotaStatus(context.Background(), time.Now()); err != claudetui.ErrNotYetImplemented {
		t.Errorf("QuotaStatus returned %v, want ErrNotYetImplemented", err)
	}
	if _, err := h.RefreshQuota(context.Background()); err != claudetui.ErrNotYetImplemented {
		t.Errorf("RefreshQuota returned %v, want ErrNotYetImplemented", err)
	}
	_ = h.QuotaFreshness()
	_ = h.SupportedLimitIDs()
	if _, err := h.AccountStatus(context.Background(), time.Now()); err != claudetui.ErrNotYetImplemented {
		t.Errorf("AccountStatus returned %v, want ErrNotYetImplemented", err)
	}
	if _, err := h.RefreshAccount(context.Background()); err != claudetui.ErrNotYetImplemented {
		t.Errorf("RefreshAccount returned %v, want ErrNotYetImplemented", err)
	}
	_ = h.AccountFreshness()
	// DefaultModelSnapshot() is allowed to either succeed (if live PTY is available)
	// or fail with ErrModelDiscoveryEvidenceMissing (no live PTY). Both are valid.
	_, _ = h.DefaultModelSnapshot()
	if _, err := h.ResolveModelAlias("", harnesses.ModelDiscoverySnapshot{}); err != harnesses.ErrAliasNotResolvable {
		t.Errorf("ResolveModelAlias returned %v, want ErrAliasNotResolvable", err)
	}
	_ = h.SupportedAliases()

	// Ensure var _ assertions are present in the source.
	checkCompileTimeAssertions(t)
}

// checkCompileTimeAssertions verifies the var _ block exists in harness.go.
func checkCompileTimeAssertions(t *testing.T) {
	t.Helper()
	repoRoot := findRepoRoot(t)
	fset := token.NewFileSet()
	path := filepath.Join(repoRoot, "internal", "harnesses", "claude-tui", "harness.go")
	file, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}

	found := make(map[string]bool)
	ast.Inspect(file, func(n ast.Node) bool {
		if decl, ok := n.(*ast.GenDecl); ok && decl.Tok == token.VAR {
			for _, spec := range decl.Specs {
				if vs, ok := spec.(*ast.ValueSpec); ok {
					// Check if this is a blank identifier assignment with a type.
					if len(vs.Names) == 1 && vs.Names[0].Name == "_" && vs.Type != nil {
						// The Type field contains the interface type being asserted.
						if sel, ok := vs.Type.(*ast.SelectorExpr); ok {
							if ident, ok := sel.X.(*ast.Ident); ok {
								typ := fmt.Sprintf("%s.%s", ident.Name, sel.Sel.Name)
								found[typ] = true
							}
						}
					}
				}
			}
		}
		return true
	})

	required := []string{
		"harnesses.Harness",
		"harnesses.QuotaHarness",
		"harnesses.AccountHarness",
		"harnesses.ModelDiscoveryHarness",
	}
	for _, req := range required {
		if !found[req] {
			t.Errorf("missing compile-time assertion for %s", req)
		}
	}
}

