package claude

import (
	"context"
	"fmt"
	"strings"
	"time"

	"golang.org/x/sync/singleflight"

	"github.com/easel/fizeau/internal/harnesses"
)

// claudeQuotaFreshness is the constant freshness window for claude quota
// evidence. Mirrors defaultClaudeQuotaStaleAfter (kept as a separate name
// so the CONTRACT-004 method has a stable, contract-named constant).
const claudeQuotaFreshness = defaultClaudeQuotaStaleAfter

// claudeAccountFreshness is the constant freshness window for claude
// account evidence. Claude embeds account info in its quota probe so the
// account refresh cadence matches quota.
const claudeAccountFreshness = defaultClaudeQuotaStaleAfter

// supportedLimitIDs is the stable public set of Windows[].LimitID values
// claude's quota probe emits. Mirrored in doc.go for human readers.
var supportedLimitIDs = []string{
	"session",
	"weekly-all",
	"weekly-sonnet",
	"extra",
}

// supportedAliases is the stable public set of family aliases
// ResolveModelAlias recognizes. Mirrored in doc.go for human readers.
var supportedAliases = []string{"sonnet", "opus", "haiku"}

// refreshGroup serializes concurrent RefreshQuota / RefreshAccount calls
// across all *Runner instances. Per CONTRACT-004 invariant #6 Runners are
// stateless wrappers — sharing the singleflight group at package scope
// keeps single-flight semantics correct when callers construct fresh
// runner instances per call (which the dispatcher does today).
var refreshGroup singleflight.Group

// QuotaProbeFunc is the signature of the PTY-quota probe that
// Runner.RefreshQuota delegates to. Exposing it as a named type keeps
// the SetCaptureForTest seam decoupled from the internal ptyquota
// package; the test seam discards the ptyquota.Result that the live
// probe returns.
type QuotaProbeFunc func(ctx context.Context, timeout time.Duration, opts ...QuotaPTYOption) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error)

// captureQuotaProbe is the live PTY probe used by RefreshQuota. It is a
// package-level variable so tests can swap it via SetCaptureForTest
// without spawning the claude binary. The default delegates to
// captureClaudeQuotaViaPTY and discards the ptyquota.Result.
var captureQuotaProbe QuotaProbeFunc = func(ctx context.Context, timeout time.Duration, opts ...QuotaPTYOption) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	windows, account, _, err := captureClaudeQuotaViaPTY(ctx, timeout, opts...)
	return windows, account, err
}

// SetCaptureForTest swaps the package-level PTY probe used by
// Runner.RefreshQuota and returns a restore function. Production code
// MUST NOT call this — it exists so service-level tests can inject
// deterministic PTY responses while exercising the real cache I/O
// inside Runner.refreshQuotaLocked. The call also forgets any
// in-flight RefreshQuota cohort so the next caller runs a fresh
// single-flight execution against the new probe instead of piggybacking
// on a prior test's probe.
func SetCaptureForTest(fn QuotaProbeFunc) func() {
	prev := captureQuotaProbe
	captureQuotaProbe = fn
	refreshGroup.Forget("claude:refresh-quota")
	return func() {
		captureQuotaProbe = prev
		refreshGroup.Forget("claude:refresh-quota")
	}
}

// QuotaStatus implements harnesses.QuotaHarness. It reads the cached
// snapshot owned by this harness and projects it onto QuotaStatus. A
// missing or undecodable cache is reported as State=QuotaUnavailable on
// a valid QuotaStatus value (no error) per CONTRACT-004 §"Errors are
// reserved for call failure."
func (r *Runner) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
	if err := ctx.Err(); err != nil {
		return harnesses.QuotaStatus{}, err
	}
	snap, ok := readClaudeQuota()
	if !ok || snap == nil {
		return harnesses.QuotaStatus{
			Source:            "cache",
			State:             harnesses.QuotaUnavailable,
			RoutingPreference: harnesses.RoutingPreferenceUnknown,
			Reason:            "no cached snapshot",
		}, nil
	}
	return claudeQuotaStatusFromSnapshot(snap, now), nil
}

// RefreshQuota implements harnesses.QuotaHarness. It probes the claude
// CLI via PTY unconditionally and persists the result through the
// harness's owned cache. Single-flight per harness: concurrent callers
// share one cohort and observe the just-written cached state. Probe
// failure (binary missing, PTY error, parse failure) is reported as
// State=QuotaUnavailable on a valid QuotaStatus value, not as an error.
func (r *Runner) RefreshQuota(ctx context.Context) (harnesses.QuotaStatus, error) {
	if err := ctx.Err(); err != nil {
		return harnesses.QuotaStatus{}, err
	}
	v, err, _ := refreshGroup.Do("claude:refresh-quota", func() (any, error) {
		return r.refreshQuotaLocked(ctx), nil
	})
	if err != nil {
		return harnesses.QuotaStatus{}, err
	}
	return v.(harnesses.QuotaStatus), nil
}

// refreshQuotaLocked is the single-flight critical section. It probes
// PTY, writes the cache on success, and returns the projected status.
// Probe failure is folded into State=QuotaUnavailable.
func (r *Runner) refreshQuotaLocked(ctx context.Context) harnesses.QuotaStatus {
	now := time.Now()
	timeout := claudeQuotaFreshness
	if deadline, ok := ctx.Deadline(); ok {
		remaining := time.Until(deadline)
		if remaining > 0 && remaining < timeout {
			timeout = remaining
		}
	}
	var opts []QuotaPTYOption
	if r.Binary != "" {
		opts = append(opts, WithQuotaPTYCommand(r.Binary))
	}
	windows, account, err := captureQuotaProbe(ctx, timeout, opts...)
	if err != nil {
		state := harnesses.QuotaUnavailable
		reason := err.Error()
		if strings.Contains(strings.ToLower(reason), "not found in path") {
			state = harnesses.QuotaUnauthenticated
		}
		return harnesses.QuotaStatus{
			Source:            "pty",
			CapturedAt:        now.UTC(),
			State:             state,
			RoutingPreference: harnesses.RoutingPreferenceUnknown,
			Reason:            reason,
		}
	}
	snap := claudeQuotaSnapshotFromWindows(windows, account)
	if path, pathErr := claudeQuotaCachePath(); pathErr == nil {
		_ = writeClaudeQuota(path, snap)
	}
	return claudeQuotaStatusFromSnapshot(&snap, now)
}

// QuotaFreshness implements harnesses.QuotaHarness.
func (r *Runner) QuotaFreshness() time.Duration {
	return claudeQuotaFreshness
}

// SupportedLimitIDs implements harnesses.QuotaHarness.
func (r *Runner) SupportedLimitIDs() []string {
	return append([]string(nil), supportedLimitIDs...)
}

// AccountStatus implements harnesses.AccountHarness. Claude embeds
// account/plan info inside its quota probe, so this method projects the
// quota cache's Account field onto AccountSnapshot.
func (r *Runner) AccountStatus(ctx context.Context, now time.Time) (harnesses.AccountSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return harnesses.AccountSnapshot{}, err
	}
	snap, ok := readClaudeQuota()
	if !ok || snap == nil {
		return harnesses.AccountSnapshot{Source: "cache"}, nil
	}
	return claudeAccountSnapshotFromQuotaSnapshot(snap, now), nil
}

// RefreshAccount implements harnesses.AccountHarness by driving the
// quota probe (which carries account evidence) and projecting the
// resulting cached snapshot onto AccountSnapshot.
func (r *Runner) RefreshAccount(ctx context.Context) (harnesses.AccountSnapshot, error) {
	if _, err := r.RefreshQuota(ctx); err != nil {
		return harnesses.AccountSnapshot{}, err
	}
	return r.AccountStatus(ctx, time.Now())
}

// AccountFreshness implements harnesses.AccountHarness.
func (r *Runner) AccountFreshness() time.Duration {
	return claudeAccountFreshness
}

// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness. It calls
// the live PTY discovery helper with a sensible timeout; on failure,
// returns ErrModelDiscoveryEvidenceMissing per the no-static-fallback principle.
func (r *Runner) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
	timeout := 10 * time.Second
	var opts []QuotaPTYOption
	if r.Binary != "" {
		opts = append(opts, WithQuotaPTYCommand(r.Binary))
	}
	snapshot, err := ReadClaudeModelDiscoveryViaPTY(timeout, opts...)
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery PTY: %w", err)
	}
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
	}
	return snapshot, nil
}

// ResolveModelAlias implements harnesses.ModelDiscoveryHarness. Returns
// harnesses.ErrAliasNotResolvable when the supplied family is not a
// recognized claude alias or when the supplied discovery snapshot has
// no concrete model matching the family.
func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
	normalized := strings.ToLower(strings.TrimSpace(family))
	if !isSupportedClaudeAlias(normalized) {
		return "", harnesses.ErrAliasNotResolvable
	}
	resolved := resolveClaudeFamilyAlias(normalized, snapshot)
	if resolved == "" {
		return "", harnesses.ErrAliasNotResolvable
	}
	return resolved, nil
}

// SupportedAliases implements harnesses.ModelDiscoveryHarness.
func (r *Runner) SupportedAliases() []string {
	return append([]string(nil), supportedAliases...)
}

func isSupportedClaudeAlias(family string) bool {
	for _, a := range supportedAliases {
		if a == family {
			return true
		}
	}
	return false
}

// claudeQuotaStatusFromSnapshot projects the per-harness snapshot onto
// harnesses.QuotaStatus, deriving State and RoutingPreference via the
// existing internal routing helper so today's "PreferClaude +
// freshness" semantics map cleanly onto CONTRACT-004's RoutingPreference
// enum.
func claudeQuotaStatusFromSnapshot(snap *claudeQuotaSnapshot, now time.Time) harnesses.QuotaStatus {
	decision := decideClaudeQuotaRouting(snap, now, claudeQuotaFreshness)
	pref, state := mapClaudeRoutingPreference(decision)
	status := harnesses.QuotaStatus{
		Source:            snap.Source,
		CapturedAt:        snap.CapturedAt,
		Fresh:             decision.Fresh,
		Age:               decision.Age,
		State:             state,
		Windows:           append([]harnesses.QuotaWindow(nil), snap.Windows...),
		RoutingPreference: pref,
		Reason:            quotaReasonForProjection(decision, state),

	// Timeout is the wall-clock cap for the entire request. 0 disables.
	Timeout time.Duration

	// IdleTimeout is the streaming-quiet cap. 0 uses harness default.
	IdleTimeout time.Duration

	// SessionLogDir overrides the per-run session-log directory; harness
	// uses this to direct progress traces into a per-bundle evidence dir.
	SessionLogDir string

	// SessionID is a stable identifier for the run, used in progress log
	// filenames and event metadata. Empty means the harness generates one.
	SessionID string

	// Metadata is echoed back into Event.Metadata (e.g. bead_id, attempt_id).
	Metadata map[string]string
}

// Harness is the internal contract every harness implementation in
// internal/harnesses/<name> satisfies. It is the minimal surface the agent
// dispatcher needs to route a resolved request into a backend.
//
// A Harness is responsible for emitting events on the returned channel until
// execution completes; the channel MUST be closed after the final event so
// downstream consumers can detect end-of-stream. The final event is always
// of type EventTypeFinal.
type Harness interface {
	// Info returns identity + capability metadata for this harness.
	Info() HarnessInfo

	// HealthCheck triggers a fresh probe (binary present, auth ok, etc.)
	// and returns nil if the harness is ready to execute.
	HealthCheck(ctx context.Context) error

	// Execute runs one resolved request. Events stream on the returned
	// channel; a single final event closes the stream. The first error
	// return is reserved for setup failures (binary missing, etc.) — once
	// the channel is returned, all per-run failures are reported via a
	// final event with Status != "success".
	Execute(ctx context.Context, req ExecuteRequest) (<-chan Event, error)
}

// QuotaStateValue is the normalized state enumeration consumed by
// CONTRACT-004 sub-interfaces. Only QuotaOK and QuotaStale carry
// routing-usable signal; other values MUST NOT result in
// RoutingPreferenceAvailable.
type QuotaStateValue string

const (
	QuotaOK              QuotaStateValue = "ok"
	QuotaStale           QuotaStateValue = "stale"
	QuotaBlocked         QuotaStateValue = "blocked"
	QuotaUnavailable     QuotaStateValue = "unavailable"
	QuotaUnauthenticated QuotaStateValue = "unauthenticated"
	QuotaUnknown         QuotaStateValue = "unknown"
)

// RoutingPreference is the routing layer's consumable signal indicating
// whether a harness should be preferred given its current quota evidence.
// It is an internal routing signal — never projected into the public
// CONTRACT-003 surface.
type RoutingPreference int

const (
	RoutingPreferenceUnknown RoutingPreference = iota
	RoutingPreferenceAvailable
	RoutingPreferenceBlocked
)

// QuotaStatus is the universal quota report defined by CONTRACT-004.
// Each harness's private snapshot type projects into this; the private
// snapshot is never exposed across package boundaries.
type QuotaStatus struct {
	// Source identifies how the underlying evidence was captured:
	// "pty", "cache", "session-token-count", "cli", "api".
	Source string

	// CapturedAt is when the underlying evidence was observed (not when
	// this status struct was assembled).
	CapturedAt time.Time

	// Fresh reports whether CapturedAt is within QuotaFreshness() at the
	// time of the call.
	Fresh bool

	// Age is now - CapturedAt at the time of the call.
	Age time.Duration

	// State is the normalized state. Only QuotaOK and QuotaStale carry
	// routing-usable signal.
	State QuotaStateValue

	// Windows captures per-window evidence (5h, weekly, tier-specific).
	// Authoritative for any structured fact the routing layer or
	// operator surfaces consume — including tier breakdowns.
	Windows []QuotaWindow

	// Account is the account/plan/auth evidence captured alongside
	// quota. Nil when the harness has no concept of account or when
	// account evidence is delivered through AccountHarness only.
	Account *AccountSnapshot

	// RoutingPreference indicates whether the routing layer should
	// prefer this harness given the current evidence.
	RoutingPreference RoutingPreference

	// Reason is a short human-readable explanation of State and
	// RoutingPreference — surfaced in operator views and routing logs.
	Reason string

	// Detail is harness-specific opaque metadata for diagnostic display
	// only. Service code MAY surface it verbatim in operator views;
	// service code MUST NOT branch on its keys or values for routing
	// decisions.
	Detail map[string]string
}

// AccountSnapshot is the universal account/auth report defined by
// CONTRACT-004. Projects onto the public AccountStatus type defined in
// CONTRACT-003.

// CONTRACT-003.
type AccountSnapshot struct {
	Authenticated   bool
	Unauthenticated bool
	Email           string
	PlanType        string
	OrgName         string
	Source          string // file path, env var name, "cache", "cli"
	CapturedAt      time.Time
	Fresh           bool
	Detail          string // free-form diagnostic detail
}

// ErrAliasNotResolvable is returned by ModelDiscoveryHarness.ResolveModelAlias
// when the requested family is not recognized or the supplied discovery
// snapshot has no matching concrete model.
var ErrAliasNotResolvable = errors.New("model alias not resolvable from snapshot")

// ErrModelDiscoveryEvidenceMissing is returned by ModelDiscoveryHarness.DefaultModelSnapshot
// when live evidence cannot be obtained (PTY failure, parse failure, etc.) and
// no static fallback is available per the no-static-fallback principle.
var ErrModelDiscoveryEvidenceMissing = errors.New("model discovery evidence missing")

// QuotaHarness is implemented by harnesses that own a subscription or
// quota window. See CONTRACT-004 for the full normative contract.
type QuotaHarness interface {
	Harness

	// QuotaStatus returns the current quota state from the harness's
	// owned cache, with Fresh/Age computed against now. MUST be cheap
	// (no live probe) and safe to call on every routing decision.
	// Absence of evidence is reported via State=QuotaUnavailable on a
	// valid QuotaStatus value; the error return is reserved for call
	// failure (ctx cancelled, IO failure, lock acquisition failure).
	QuotaStatus(ctx context.Context, now time.Time) (QuotaStatus, error)

	// RefreshQuota drives the harness's live probe, persists the
	// result through the harness's owned cache, and returns the
	// resulting status. Single-flight per harness instance via the
	// harness's cache lock; concurrent callers block. Probe failure
	// is reported as a QuotaStatus with State=QuotaUnavailable (or
	// QuotaUnauthenticated for auth-related failures), not as an
	// error. The error return is reserved for call failure.
	RefreshQuota(ctx context.Context) (QuotaStatus, error)

	// QuotaFreshness returns the harness's freshness window (e.g. 15m).
	// Constant for the harness; cheap to call.
	QuotaFreshness() time.Duration

	// SupportedLimitIDs returns the harness's stable set of emitted
	// Windows[].LimitID values. Constant for the harness; the
	// conformance suite reads this value to verify that emitted
	// Windows[].LimitID strings are a subset of this set. Empty
	// slice is allowed for harnesses that emit no windows.
	SupportedLimitIDs() []string
}

// AccountHarness is implemented by harnesses that expose authentication
// or account state independent of quota. See CONTRACT-004 for the full
// normative contract.
type AccountHarness interface {
	Harness

	// AccountStatus returns the harness's current account/auth state.
	// Cheap; reads cached evidence only. Absence of evidence is
	// reported via AccountSnapshot fields on a valid snapshot; the
	// error return is reserved for call failure.
	AccountStatus(ctx context.Context, now time.Time) (AccountSnapshot, error)

	// RefreshAccount drives the harness's account probe and persists
	// the result. Single-flight per harness instance; concurrent
	// callers block. Probe failure is reported via AccountSnapshot
	// fields, not as an error.
	RefreshAccount(ctx context.Context) (AccountSnapshot, error)

	// AccountFreshness returns the harness's account freshness window
	// (e.g. 7 days for gemini). Constant for the harness; cheap.
	AccountFreshness() time.Duration
}

// ModelDiscoveryHarness is implemented by harnesses whose model surface
// extends beyond a single Info().DefaultModel — i.e. they support family
// aliases (sonnet, gpt, gemini) that resolve through discovery evidence.
// See CONTRACT-004 for the full normative contract.
type ModelDiscoveryHarness interface {
	Harness

	// DefaultModelSnapshot returns the harness's seed/fallback
	// discovery snapshot. Used to bootstrap the catalog before the
	// first live refresh lands. Per the no-static-fallback principle,
	// returns ErrModelDiscoveryEvidenceMissing when live evidence cannot
	// be obtained; never returns a cached or literal fallback.
	DefaultModelSnapshot() (ModelDiscoverySnapshot, error)

	// ResolveModelAlias maps a family-style requested model to a
	// concrete model ID using the provided discovery snapshot.
	// Returns ErrAliasNotResolvable if the family is not recognized
	// or the snapshot has no matching concrete model.
	ResolveModelAlias(family string, snapshot ModelDiscoverySnapshot) (string, error)

	// SupportedAliases returns the harness's stable set of family
	// aliases ResolveModelAlias recognizes. Constant for the harness;
	// the conformance suite uses this value to verify
	// ResolveModelAlias covers each documented family (positive path)
	// and rejects out-of-set families with ErrAliasNotResolvable
	// (negative path). Empty slice is allowed for harnesses that
	// recognize no family aliases.
	SupportedAliases() []string
}

