package claude

import (
	"context"
	"fmt"
	"os/exec"
	"regexp"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/harnesses/ptyquota"
	"github.com/easel/fizeau/internal/pty/cassette"
	"github.com/easel/fizeau/internal/pty/session"
)

const ClaudeModelDiscoveryFreshnessWindow = 24 * time.Hour

var (
	claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
	claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
	claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
	claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
	claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
)

func ReadClaudeModelDiscoveryViaPTY(timeout time.Duration, opts ...QuotaPTYOption) (harnesses.ModelDiscoverySnapshot, error) {
	cfg := quotaPTYOptions{binary: "claude"}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}
	var snapshot harnesses.ModelDiscoverySnapshot
	_, err := ptyquota.Run(context.Background(), ptyquota.Config{
		HarnessName:  "claude",
		Binary:       cfg.binary,
		Args:         cfg.args,
		Workdir:      cfg.workdir,
		Env:          cfg.env,
		Command:      "/model\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     claudeModelDiscoveryComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		CassetteDir:  cfg.cassetteDir,
		Discovery: func(text string) (cassette.DiscoveryRecord, error) {
			snapshot = claudeDiscoveryFromText(text, "pty")
			if len(snapshot.Models) == 0 {
				return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in claude /model output")
			}
			return discoveryRecord(snapshot), nil
		},
	})
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, err
	}
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude /model output")
	}
	return snapshot, nil
}

func ReadClaudeModelDiscoveryFromCassette(dir string) (harnesses.ModelDiscoverySnapshot, error) {
	reader, err := cassette.Open(dir)
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, err
	}
	if rec := reader.Discovery(); rec != nil && len(rec.Models) > 0 {
		return snapshotFromDiscoveryRecord(*rec), nil
	}
	text := reader.Final().FinalText
	if text == "" {
		frames := reader.Frames()
		if len(frames) > 0 {
			text = strings.Join(frames[len(frames)-1].Text, "\n")
		}
	}
	snapshot := claudeDiscoveryFromText(text, "cassette")
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude model cassette")
	}
	return snapshot, nil
}

func readClaudeReasoningFromHelp(ctx context.Context, binary string, args ...string) ([]string, error) {
	if binary == "" {
		binary = "claude"
	}
	if len(args) == 0 {
		args = []string{"--help"}
	}
	cmd := exec.CommandContext(ctx, binary, args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("claude help: %w", err)
	}
	levels := parseClaudeReasoningLevels(string(out))
	if len(levels) == 0 {
		return nil, fmt.Errorf("claude help did not expose --effort levels")
	}
	return levels, nil
}

// testClaudeModelDiscovery returns a minimal discovery snapshot for testing.
// It is not used in production code paths.
func testClaudeModelDiscovery() harnesses.ModelDiscoverySnapshot {
	return harnesses.ModelDiscoverySnapshot{
		CapturedAt:      time.Now().UTC(),
		ReasoningLevels: []string{"low", "medium", "high", "xhigh", "max"},
		FreshnessWindow: ClaudeModelDiscoveryFreshnessWindow.String(),
	}
}

func claudeModelDiscoveryComplete(text string) bool {
	return len(parseClaudeModels(text)) > 0
}

func claudeDiscoveryFromText(text, source string) harnesses.ModelDiscoverySnapshot {
	snapshot := harnesses.ModelDiscoverySnapshot{
		CapturedAt:      time.Now().UTC(),
		FreshnessWindow: ClaudeModelDiscoveryFreshnessWindow.String(),
	}
	if source != "" {
		snapshot.Source = source
	}
	if models := parseClaudeModels(text); len(models) > 0 {
		snapshot.Models = models
	}
	if levels := parseClaudeReasoningLevels(text); len(levels) > 0 {
		snapshot.ReasoningLevels = levels
	}
	return snapshot
}

func parseClaudeModels(text string) []string {
	text = stripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lower := strings.ToLower(text)
	models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
	for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 3 {
			models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
		}
	}
	for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 2 {
			models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
		}
	}
	for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 1 {
			models = appendUniqueString(models, match[1])
		}
	}
	return models
}

func resolveClaudeFamilyAlias(model string, snapshot harnesses.ModelDiscoverySnapshot) string {
	family := strings.ToLower(strings.TrimSpace(model))
	if family != "sonnet" && family != "opus" && family != "haiku" {
		return model
	}
	if resolved := latestClaudeFamilyVersion(family, snapshot.Models); resolved != "" {
		return resolved
	}
	return model
}

func latestClaudeFamilyVersion(family string, models []string) string {
	prefix := family + "-"
	best := ""
	var bestParts []int
	for _, model := range models {
		model = strings.ToLower(strings.TrimSpace(model))
		if !strings.HasPrefix(model, prefix) {
			continue
		}
		parts, ok := parseClaudeVersionParts(strings.TrimPrefix(model, prefix))
		if !ok {
			continue
		}
		if best == "" || compareVersionParts(parts, bestParts) > 0 {
			best = model
			bestParts = parts
		}
	}
	return best
}

func parseClaudeVersionParts(version string) ([]int, bool) {
	version = strings.ReplaceAll(version, "-", ".")
	raw := strings.Split(version, ".")
	if len(raw) == 0 {
		return nil, false
	}
	parts := make([]int, 0, len(raw))
	for _, part := range raw {
		if part == "" {
			return nil, false
		}
		n := 0
		for _, r := range part {
			if r < '0' || r > '9' {
				return nil, false
			}
			n = n*10 + int(r-'0')
		}
		parts = append(parts, n)
	}
	return parts, true
}

func compareVersionParts(a, b []int) int {
	n := len(a)
	if len(b) > n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		av, bv := 0, 0
		if i < len(a) {
			av = a[i]
		}
		if i < len(b) {
			bv = b[i]
		}
		if av > bv {
			return 1
		}
		if av < bv {
			return -1
		}
	}
	return 0
}

func parseClaudeReasoningLevels(text string) []string {
	text = stripANSI(strings.ReplaceAll(text, "\n", " "))
	m := claudeEffortPattern.FindStringSubmatch(text)
	if len(m) < 2 {
		return nil
	}
	parts := strings.Split(m[1], ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		out = appendUniqueString(out, strings.TrimSpace(part))
	}
	return out
}

func discoveryRecord(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
	return cassette.DiscoveryRecord{
		Source:            snapshot.Source,
		Status:            string(ptyquota.StatusOK),
		Models:            append([]string(nil), snapshot.Models...),
		ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
		CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
		FreshnessWindow:   snapshot.FreshnessWindow,
		StalenessBehavior: "stale model discovery evidence requires authenticated PTY refresh before capability promotion",
		Metadata:          map[string]any{"detail": snapshot.Detail},
	}

package ptyquota

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"time"

	"github.com/easel/fizeau/internal/pty/cassette"
	"github.com/easel/fizeau/internal/pty/session"
	"github.com/easel/fizeau/internal/pty/terminal"
	"github.com/easel/fizeau/internal/safefs"
)

type Status string

const (
	StatusOK              Status = "ok"
	StatusUnavailable     Status = "unavailable"
	StatusUnauthenticated Status = "unauthenticated"
	StatusError           Status = "error"
)

type ProbeError struct {
	Status Status
	Reason string
	Err    error
}

func (e *ProbeError) Error() string {
	if e == nil {
		return ""
	}
	reason := e.Reason
	if reason == "" {
		reason = string(e.Status)
	}
	if e.Err == nil {
		return reason
	}
	return reason + ": " + e.Err.Error()
}

func (e *ProbeError) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Err
}

func ErrorStatus(err error) Status {
	if err == nil {
		return StatusOK
	}
	var probeErr *ProbeError
	if errors.As(err, &probeErr) {
		return probeErr.Status
	}
	return StatusError
}

type Config struct {
	HarnessName string
	Binary      string
	// BinaryVersion is stamped into accepted cassette manifests. When empty,
	// Run makes a best-effort short --version probe and records "unknown" if
	// the harness does not answer quickly.
	BinaryVersion string
	Args          []string
	Workdir       string
	Env           []string

	Command            string
	ReadyMarkers       []string
	DoneMarkers        []string
	DoneAnyMarkers     []string
	DoneWhen           func(string) bool
	ResetBeforeCommand bool
	Timeout            time.Duration
	Size               session.Size

	CassetteDir string
	Quota       func(string) (cassette.QuotaRecord, error)
	Discovery   func(string) (cassette.DiscoveryRecord, error)
}

type Result struct {
	Text        string
	CassetteDir string
	Status      Status
}

func Run(ctx context.Context, cfg Config) (Result, error) {
	cfg = defaultConfig(cfg)
	if cfg.Binary == "" {
		return Result{}, &ProbeError{Status: StatusUnavailable, Reason: "quota probe binary is empty"}
	}
	binaryPath, err := exec.LookPath(cfg.Binary)
	if err != nil {
		return Result{}, &ProbeError{Status: StatusUnavailable, Reason: cfg.Binary + " not found in PATH", Err: err}
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if cfg.BinaryVersion == "" {
		cfg.BinaryVersion = "unknown"
		if shouldProbeBinaryVersion(cfg.HarnessName, binaryPath) {
			cfg.BinaryVersion = detectBinaryVersion(ctx, binaryPath)
		}
	}
	ctx, cancel := context.WithTimeout(ctx, cfg.Timeout)
	defer cancel()

	recordDir, commitDir, err := prepareRecordDir(cfg.CassetteDir)
	if err != nil {
		return Result{}, &ProbeError{Status: StatusError, Reason: "prepare quota cassette", Err: err}
	}
	var rec *cassette.Recorder
	if recordDir != "" {
		rec, err = cassette.Create(recordDir, manifestFor(cfg))
		if err != nil {
			cleanupRecordDir(recordDir, commitDir)
			return Result{}, &ProbeError{Status: StatusError, Reason: "create quota cassette", Err: err}
		}
	}

	emu := terminal.New(terminal.Size{Rows: int(cfg.Size.Rows), Cols: int(cfg.Size.Cols)})
	s, err := session.Start(ctx, binaryPath, cfg.Args, cfg.Workdir, probeEnv(cfg.Env), cfg.Size, session.WithTimeout(cfg.Timeout), session.WithBufferSize(4096))
	if err != nil {
		closeDiscard(rec)
		cleanupRecordDir(recordDir, commitDir)
		return Result{}, classifyFailure(cfg.HarnessName, "", err)
	}

	run := &runState{
		session:  s,
		rec:      rec,
		emu:      emu,
		size:     terminal.Size{Rows: int(cfg.Size.Rows), Cols: int(cfg.Size.Cols)},
		scrubber: scrubberFor(cfg),
		done:     make(chan struct{}),
	}
	go run.recordOutput()

	result, err := run.drive(ctx, cfg)
	status := session.ExitStatus{}
	if err != nil {
		_ = s.Kill()
		status = s.Wait()
		select {
		case <-run.done:
		case <-time.After(5 * time.Second):
			_ = s.Close()
		}
		closeDiscard(rec)
		cleanupRecordDir(recordDir, commitDir)
		return Result{}, classifyFailure(cfg.HarnessName, run.screen(), err)
	}
	status = stopSession(s, 5*time.Second)
	finishErr := run.finish(status, cfg)
	if finishErr != nil {
		closeDiscard(rec)
		cleanupRecordDir(recordDir, commitDir)
		return Result{}, &ProbeError{Status: StatusError, Reason: "finish quota probe", Err: finishErr}
	}
	if rec != nil {
		if err := commitRecordDir(recordDir, commitDir); err != nil {
			cleanupRecordDir(recordDir, commitDir)
			return Result{}, &ProbeError{Status: StatusError, Reason: "commit quota cassette", Err: err}
		}
		result.CassetteDir = commitDir
	}
	result.Status = StatusOK
	return result, nil
}

func defaultConfig(cfg Config) Config {
	if cfg.HarnessName == "" {
		cfg.HarnessName = cfg.Binary
	}
	if cfg.Timeout <= 0 {
		cfg.Timeout = 30 * time.Second
	}
	if cfg.Size.Rows == 0 {
		cfg.Size.Rows = 50
	}
	if cfg.Size.Cols == 0 {
		cfg.Size.Cols = 220
	}
	return cfg
}

type runState struct {
	mu        sync.Mutex
	session   *session.Session
	rec       *cassette.Recorder
	emu       *terminal.VT10x
	latest    terminal.Frame
	frameSeen bool
	size      terminal.Size
	outputErr error
	frames    int
	rawBytes  int64
	raw       bytes.Buffer
	scrubber  *cassette.Scrubber
	report    cassette.ScrubReport
	done      chan struct{}
}

func (r *runState) drive(ctx context.Context, cfg Config) (Result, error) {
	if len(cfg.ReadyMarkers) > 0 {
		if err := r.waitForAnyText(ctx, cfg.ReadyMarkers...); err != nil {
			return Result{}, err
		}
	}
	if cfg.ResetBeforeCommand {
		r.resetTerminal()
	}
	if cfg.Command != "" {
		if err := r.sendBytes([]byte(cfg.Command)); err != nil {
			return Result{}, err
		}
	}
	if len(cfg.DoneMarkers) > 0 || cfg.DoneWhen != nil {
		if err := r.waitForText(ctx, cfg.DoneMarkers, cfg.DoneAnyMarkers, cfg.DoneWhen); err != nil {
			return Result{}, err
		}
	}
	text := r.screen()
	if cfg.Quota != nil {
		quota, err := cfg.Quota(text)
		if err != nil {
			return Result{}, err
		}
		if r.rec != nil {
			if err := r.rec.WriteQuota(quota); err != nil {
				return Result{}, err
			}
		}
	}
	if cfg.Discovery != nil {
		discovery, err := cfg.Discovery(text)
		if err != nil {
			return Result{}, err
		}
		if r.rec != nil {
			if err := r.rec.WriteDiscovery(discovery); err != nil {
				return Result{}, err
			}
		}
	}
	return Result{Text: text}, nil
}

func (r *runState) recordOutput() {
	defer close(r.done)
	for chunk := range r.session.Output() {
		if chunk.ReadError != nil && !errors.Is(chunk.ReadError, io.EOF) {
			r.mu.Lock()
			r.outputErr = chunk.ReadError
			r.mu.Unlock()
			return
		}
		if len(chunk.Bytes) == 0 {
			continue
		}
		r.mu.Lock()
		_, _ = r.raw.Write(chunk.Bytes)
		frame, err := r.emu.Feed(chunk.Bytes)
		if err != nil {
