type ClaudeAccountObservation struct {
	Account       *harnesses.AccountInfo
	Authenticated bool
	Unauthenticated bool
	Raw           string
	Detail        string
}

// ParseClaudeAccountObservation parses interactive Claude status output into a
// neutral account observation.
func ParseClaudeAccountObservation(text string) (ClaudeAccountObservation, error) {
	cleaned := StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	trimmed := strings.TrimSpace(cleaned)
	if trimmed == "" {
		return ClaudeAccountObservation{}, fmt.Errorf("empty claude status output")
	}

	obs := ClaudeAccountObservation{Raw: trimmed}
	if parseClaudeAccountObservationJSON(trimmed, &obs) {
		return obs, nil
	}
	if parseClaudeAccountObservationText(trimmed, &obs) {
		return obs, nil
	}
	return ClaudeAccountObservation{}, fmt.Errorf("no account evidence found in claude status output")
}

// ClaudeAccountObservationComplete reports whether the current screen appears to
// contain a usable account-status observation.
func ClaudeAccountObservationComplete(text string) bool {
	obs, err := ParseClaudeAccountObservation(text)
	return err == nil && (obs.Authenticated || obs.Unauthenticated || obs.Account != nil)
}

type claudeQuotaObservation struct {
	Windows []harnesses.QuotaWindow
	Account *harnesses.AccountInfo
	Raw     string
}

// ParseClaudeQuotaObservation parses a Claude /usage screen into windows and
// account metadata.
func ParseClaudeQuotaObservation(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	cleaned := StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	trimmed := strings.TrimSpace(cleaned)
	if trimmed == "" {
		return nil, nil, fmt.Errorf("empty claude usage output")
	}
	windows, account := parseClaudeQuotaObservationText(trimmed)
	if len(windows) == 0 {
		return nil, account, fmt.Errorf("no quota windows found in claude usage output")
	}
	if err := validateClaudeQuotaEvidence(windows, account); err != nil {
		return nil, account, err
	}
	return windows, account, nil
}

// ClaudeQuotaObservationComplete reports whether the current screen contains a
// complete /usage observation.
func ClaudeQuotaObservationComplete(text string) bool {
	windows, account := parseClaudeQuotaObservationText(text)
	if len(windows) == 0 {
		return false
	}
	return accountPlan(account) != ""
}

func parseClaudeAccountObservationJSON(text string, obs *ClaudeAccountObservation) bool {
	if !strings.HasPrefix(strings.TrimSpace(text), "{") {
		return false
	}
	var payload map[string]any
	if err := json.Unmarshal([]byte(text), &payload); err != nil {
		return false
	}
	obs.Detail = summarizeClaudeJSON(payload)
	if loggedIn, ok := boolField(payload, "loggedIn", "logged_in", "authenticated", "isAuthenticated", "logged_in_user"); ok {
		obs.Authenticated = loggedIn
		obs.Unauthenticated = !loggedIn
	}
	if status := strings.ToLower(strings.TrimSpace(stringField(payload, "status", "state", "authStatus", "auth_status"))); status != "" {
		switch {
		case strings.Contains(status, "not logged"), strings.Contains(status, "unauth"):
			obs.Unauthenticated = true
			obs.Authenticated = false
		case strings.Contains(status, "auth") || strings.Contains(status, "logged"):
			obs.Authenticated = true
			obs.Unauthenticated = false
		}
	}
	account := accountInfoFromFields(payload)
	if account != nil {
		obs.Account = account
		obs.Authenticated = true
		obs.Unauthenticated = false
	}
	return obs.Authenticated || obs.Unauthenticated || obs.Account != nil
}

func parseClaudeAccountObservationText(text string, obs *ClaudeAccountObservation) bool {
	lower := strings.ToLower(text)
	switch {
	case strings.Contains(lower, "not logged in"),
		strings.Contains(lower, "please run /login"),
		strings.Contains(lower, "invalid api key"),
		strings.Contains(lower, "auth conflict"):
		obs.Unauthenticated = true
		obs.Authenticated = false
	}

	account := accountInfoFromText(text)
	if account != nil {
		obs.Account = account
		obs.Authenticated = true
		obs.Unauthenticated = false
	}
	if obs.Account == nil {
		if strings.Contains(lower, "logged in") || strings.Contains(lower, "authenticated") {
			obs.Authenticated = true
		}
	}
	if obs.Authenticated || obs.Unauthenticated || obs.Account != nil {
		if obs.Detail == "" {
			obs.Detail = trimmedSummary(text)
		}
		return true
	}
	return false
}

func accountInfoFromFields(fields map[string]any) *harnesses.AccountInfo {
	account := &harnesses.AccountInfo{}
	account.Email = firstStringField(fields, "email", "accountEmail", "account_email", "userEmail", "user_email")
	account.OrgName = firstStringField(fields, "orgName", "org_name", "organization", "organizationName", "workspace", "workspaceName")
	account.PlanType = normalizeClaudePlanType(firstAccountPlanField(fields))
	if account.PlanType == "" && account.Email == "" && account.OrgName == "" {
		return nil
	}
	return account
}

func accountInfoFromText(text string) *harnesses.AccountInfo {
	account := &harnesses.AccountInfo{}
	lines := strings.Split(text, "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if m := claudeAccountLinePattern.FindStringSubmatch(trimmed); len(m) == 2 {
			value := strings.TrimSpace(m[1])
			account.Email = account.Email
			switch {
			case strings.HasPrefix(strings.ToLower(trimmed), "email"):
				if account.Email == "" {
					account.Email = findClaudeEmail(value)
				}
			case strings.HasPrefix(strings.ToLower(trimmed), "organization"), strings.HasPrefix(strings.ToLower(trimmed), "org"):
				if account.OrgName == "" {
					account.OrgName = value
				}
			default:
				if plan := firstClaudePlan(value); plan != "" && account.PlanType == "" {
					account.PlanType = plan
				}
			}
			continue
		}
		if account.PlanType == "" {
			if plan := firstClaudePlan(trimmed); plan != "" {
				account.PlanType = plan
				continue
			}
		}
		if account.Email == "" {
			if email := findClaudeEmail(trimmed); email != "" {
				account.Email = email
				continue
			}
		}
		if account.OrgName == "" {
			if strings.Contains(strings.ToLower(trimmed), "org") && !strings.Contains(strings.ToLower(trimmed), "auth") {
				account.OrgName = trimmed
			}
		}
	}
	if account.PlanType == "" && account.Email == "" && account.OrgName == "" {
		return nil
	}
	return account
}

func firstClaudePlan(text string) string {
	if m := claudeAccountPlanPattern.FindStringSubmatch(text); len(m) > 1 {
		return normalizeClaudePlanType(m[1])
	}
	return ""
}

func findClaudeEmail(text string) string {
	if m := claudeAccountEmailPattern.FindString(text); m != "" {
		return strings.ToLower(strings.TrimSpace(m))
	}
	return ""
}

func firstAccountPlanField(fields map[string]any) string {
	for _, key := range []string{
		"subscriptionType",
		"subscription_type",
		"planType",
		"plan_type",
		"plan",
		"billingMode",
		"billing_mode",
		"account",
		"accountType",
		"account_type",
	} {
		if s := stringField(fields, key); s != "" {
			if plan := firstClaudePlan(s); plan != "" {
				return plan
			}
			return s
		}
	}
	return ""
}

func stringField(fields map[string]any, keys ...string) string {
	for _, key := range keys {
		if v, ok := fields[key]; ok {
			if s, ok := v.(string); ok {
				return strings.TrimSpace(s)
			}
		}
	}
	return ""
}

func boolField(fields map[string]any, keys ...string) (bool, bool) {
	for _, key := range keys {
		if v, ok := fields[key]; ok {
			switch b := v.(type) {
			case bool:
				return b, true
			case string:
				switch strings.ToLower(strings.TrimSpace(b)) {
				case "true", "1", "yes", "loggedin", "authenticated":
					return true, true
				case "false", "0", "no", "unauthenticated", "not logged in":
					return false, true
				}
			}
		}
	}
	return false, false
}

func summarizeClaudeJSON(fields map[string]any) string {
	parts := make([]string, 0, 4)
	for _, key := range []string{"status", "message", "authMethod", "auth_method", "subscriptionType", "subscription_type", "planType", "plan_type"} {
		if s := stringField(fields, key); s != "" {
			parts = append(parts, key+"="+s)
		}
	}
	return strings.Join(parts, ", ")
}

func trimmedSummary(text string) string {
	lines := strings.Split(strings.TrimSpace(text), "\n")
	if len(lines) > 3 {
		lines = lines[:3]
	}
	return strings.TrimSpace(strings.Join(lines, "\n"))
}

func parseClaudeQuotaObservationText(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo) {
	lines := strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n")

	var acct *harnesses.AccountInfo
	var windows []harnesses.QuotaWindow

	for _, line := range lines {
		if m := claudeQuotaPlanTypePattern.FindString(line); m != "" {
			acct = &harnesses.AccountInfo{PlanType: normalizeClaudePlanType(m)}
			break
		}
		if m := claudeQuotaStandalonePlanTypePattern.FindStringSubmatch(line); len(m) > 1 {
			acct = &harnesses.AccountInfo{PlanType: normalizeClaudePlanType(m[1])}
			break
		}
	}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		trimmedLower := strings.ToLower(trimmed)

		trimmedLower := strings.ToLower(trimmed)

		var sec *struct {
			Name       string
			LimitID    string
			WindowMins int
		}
		for j := range claudeUsageSections {
			if trimmedLower == strings.ToLower(claudeUsageSections[j].Name) {
				sec = &claudeUsageSections[j]
				break
			}
		}
		if sec == nil {
			continue
		}

		var usedPct float64
		var resetsAt string
		found := false

		for j := i + 1; j < len(lines) && j <= i+5; j++ {
			next := strings.TrimSpace(lines[j])
			if !found {
				if m := claudeQuotaUsedPercentPattern.FindStringSubmatch(next); m != nil {
					pct, _ := strconv.ParseFloat(m[1], 64)
					usedPct = pct
					found = true
				}
			}
			if found && resetsAt == "" && strings.Contains(strings.ToLower(next), "resets") {
				resetsAt = extractClaudeResetsText(next)
			}
			if found && resetsAt != "" {
				break
			}
		}

		if !found {
			continue
		}

		windows = append(windows, harnesses.QuotaWindow{
			Name:          sec.Name,
			LimitID:       sec.LimitID,
			WindowMinutes: sec.WindowMins,
			UsedPercent:   usedPct,
			ResetsAt:      resetsAt,
			State:         harnesses.QuotaStateFromUsedPercent(int(math.Ceil(usedPct))),
		})
	}

	return windows, acct
}

var claudeUsageSections = []struct {
	Name       string
	LimitID    string
	WindowMins int
}{
	{"Current session", "session", 300},
	{"Current week (all models)", "weekly-all", 10080},
	{"Current week (Sonnet only)", "weekly-sonnet", 10080},
	{"Extra usage", "extra", 0},
}

func extractClaudeResetsText(line string) string {
	lower := strings.ToLower(line)
	idx := strings.Index(lower, "resets")
	if idx < 0 {
		return ""
	}
	return strings.TrimSpace(line[idx+len("resets"):])
}

func validateClaudeQuotaEvidence(windows []harnesses.QuotaWindow, account *harnesses.AccountInfo) error {
	if accountPlan(account) == "" {
		return fmt.Errorf("missing account plan")
	}
	if !hasQuotaWindow(windows, "session") {
		return fmt.Errorf("missing session window")
	}
	if !hasQuotaWindow(windows, "weekly-all") && !hasQuotaWindow(windows, "weekly-sonnet") {
		return fmt.Errorf("missing weekly window")
	}
	return nil
}

func accountPlan(account *harnesses.AccountInfo) string {
	if account == nil {
		return ""
	}
	return account.PlanType
}

func hasQuotaWindow(windows []harnesses.QuotaWindow, limitID string) bool {
	for _, window := range windows {
		if window.LimitID == limitID {
			return true
		}
	}
	return false
}

package anthropic

import (
	"encoding/json"
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"

	"github.com/easel/fizeau/internal/harnesses"
)

var (
	claudeQuotaUsedPercentPattern        = regexp.MustCompile(`<?(\d+(?:\.\d+)?)%\s+used`)
	claudeQuotaPlanTypePattern           = regexp.MustCompile(`(?i)(Claude\s+(?:Max|Pro|Team|Enterprise|Free))`)
	claudeQuotaStandalonePlanTypePattern = regexp.MustCompile(`(?i)\b(Max|Pro|Team|Enterprise|Free)\b(?:\s+plan)?`)
	claudeAccountPlanPattern             = regexp.MustCompile(`(?i)\b(Claude\s+(?:Max|Pro|Team|Enterprise|Free)|Max|Pro|Team|Enterprise|Free)\b`)
	claudeAccountEmailPattern            = regexp.MustCompile(`(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b`)
	claudeAccountLinePattern             = regexp.MustCompile(`(?i)^(?:account|plan|billing mode|subscription|workspace|organization|org|email|status|auth method)\s*[:=]\s*(.+)$`)
)

type ClaudeAccountObservation struct {
	Account       *harnesses.AccountInfo
	Authenticated   bool
	Unauthenticated bool
	Raw             string
	Detail          string
}

// ParseClaudeAccountObservation parses interactive Claude status output into a
// neutral account observation.
func ParseClaudeAccountObservation(text string) (ClaudeAccountObservation, error) {
	cleaned := StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	trimmed := strings.TrimSpace(cleaned)
	if trimmed == "" {
		return ClaudeAccountObservation{}, fmt.Errorf("empty claude status output")
	}

	obs := ClaudeAccountObservation{Raw: trimmed}
	if parseClaudeAccountObservationJSON(trimmed, &obs) {
		return obs, nil
	}
	if parseClaudeAccountObservationText(trimmed, &obs) {
		return obs, nil
	}
	return ClaudeAccountObservation{}, fmt.Errorf("no account evidence found in claude status output")
}

// ClaudeAccountObservationComplete reports whether the current screen appears to
// contain a usable account-status observation.
func ClaudeAccountObservationComplete(text string) bool {
	obs, err := ParseClaudeAccountObservation(text)
	return err == nil && (obs.Authenticated || obs.Unauthenticated || obs.Account != nil)
}

type claudeQuotaObservation struct {
	Windows []harnesses.QuotaWindow
	Account *harnesses.AccountInfo
	Raw     string
}

// ParseClaudeQuotaObservation parses a Claude /usage screen into windows and
// account metadata.
func ParseClaudeQuotaObservation(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	cleaned := StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	trimmed := strings.TrimSpace(cleaned)
	if trimmed == "" {
		return nil, nil, fmt.Errorf("empty claude usage output")
	}
	windows, account := parseClaudeQuotaObservationText(trimmed)
	if len(windows) == 0 {
		return nil, account, fmt.Errorf("no quota windows found in claude usage output")
	}
	if err := validateClaudeQuotaEvidence(windows, account); err != nil {
		return nil, account, err
	}
	return windows, account, nil
}

// ClaudeQuotaObservationComplete reports whether the current screen contains a
// complete /usage observation.
func ClaudeQuotaObservationComplete(text string) bool {
	windows, account := parseClaudeQuotaObservationText(text)
	if len(windows) == 0 {
		return false
	}
	return accountPlan(account) != ""
}

func parseClaudeAccountObservationJSON(text string, obs *ClaudeAccountObservation) bool {
	if !strings.HasPrefix(strings.TrimSpace(text), "{") {
		return false
	}
	var payload map[string]any
	if err := json.Unmarshal([]byte(text), &payload); err != nil {
		return false
	}
	obs.Detail = summarizeClaudeJSON(payload)
	if loggedIn, ok := boolField(payload, "loggedIn", "logged_in", "authenticated", "isAuthenticated", "logged_in_user"); ok {
		obs.Authenticated = loggedIn
		obs.Unauthenticated = !loggedIn
	}
	if status := strings.ToLower(strings.TrimSpace(stringField(payload, "status", "state", "authStatus", "auth_status"))); status != "" {
		switch {
		case strings.Contains(status, "not logged"), strings.Contains(status, "unauth"):
			obs.Unauthenticated = true
			obs.Authenticated = false
		case strings.Contains(status, "auth") || strings.Contains(status, "logged"):
			obs.Authenticated = true
			obs.Unauthenticated = false
		}
	}
	account := accountInfoFromFields(payload)
	if account != nil {
		obs.Account = account
		obs.Authenticated = true
		obs.Unauthenticated = false
	}
	return obs.Authenticated || obs.Unauthenticated || obs.Account != nil
}

func parseClaudeAccountObservationText(text string, obs *ClaudeAccountObservation) bool {
	lower := strings.ToLower(text)
	switch {
	case strings.Contains(lower, "not logged in"),
		strings.Contains(lower, "please run /login"),
		strings.Contains(lower, "invalid api key"),
		strings.Contains(lower, "auth conflict"):
		obs.Unauthenticated = true
		obs.Authenticated = false
	}

	account := accountInfoFromText(text)
	if account != nil {
		obs.Account = account
		obs.Authenticated = true
		obs.Unauthenticated = false
	}
	if obs.Account == nil {
		if (strings.Contains(lower, "logged in") || strings.Contains(lower, "authenticated")) &&
			!strings.Contains(lower, "unauthenticated") &&
			!strings.Contains(lower, "not logged in") {
			obs.Authenticated = true
		}
	}
	if obs.Authenticated || obs.Unauthenticated || obs.Account != nil {
		if obs.Detail == "" {
			obs.Detail = trimmedSummary(text)
		}
		return true
	}
	return false
}

func accountInfoFromFields(fields map[string]any) *harnesses.AccountInfo {
	account := &harnesses.AccountInfo{}
	account.Email = stringField(fields, "email", "accountEmail", "account_email", "userEmail", "user_email")
	account.OrgName = stringField(fields, "orgName", "org_name", "organization", "organizationName", "workspace", "workspaceName")
	account.PlanType = normalizeClaudePlanType(firstAccountPlanField(fields))
	if account.PlanType == "" && account.Email == "" && account.OrgName == "" {
		return nil
	}
	return account
}

func accountInfoFromText(text string) *harnesses.AccountInfo {
	account := &harnesses.AccountInfo{}
	lines := strings.Split(text, "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if m := claudeAccountLinePattern.FindStringSubmatch(trimmed); len(m) == 2 {
			value := strings.TrimSpace(m[1])
			switch {
			case strings.HasPrefix(strings.ToLower(trimmed), "email"):
				if account.Email == "" {
					account.Email = findClaudeEmail(value)
				}
			case strings.HasPrefix(strings.ToLower(trimmed), "organization"), strings.HasPrefix(strings.ToLower(trimmed), "org"):
				if account.OrgName == "" {
					account.OrgName = value
				}
			default:
				if plan := firstClaudePlan(value); plan != "" && account.PlanType == "" {
					account.PlanType = plan
				}
			}
			continue
		}
		if account.PlanType == "" {
			if plan := firstClaudePlan(trimmed); plan != "" {
				account.PlanType = plan
				continue
			}
		}
		if account.Email == "" {
			if email := findClaudeEmail(trimmed); email != "" {
				account.Email = email
				continue
			}
		}
		if account.OrgName == "" {
			if strings.Contains(strings.ToLower(trimmed), "org") && !strings.Contains(strings.ToLower(trimmed), "auth") {
				account.OrgName = trimmed
			}
		}
	}
	if account.PlanType == "" && account.Email == "" && account.OrgName == "" {
		return nil
	}
	return account
}

func firstClaudePlan(text string) string {
	if m := claudeAccountPlanPattern.FindStringSubmatch(text); len(m) > 1 {
		return normalizeClaudePlanType(m[1])
	}

	if deadline, ok := ctx.Deadline(); ok {
		if remaining := time.Until(deadline); remaining > 0 && remaining < timeout {
			timeout = remaining
		}
	}
	var obs anthropic.ClaudeAccountObservation
	_, err := ptyquota.Run(ctx, ptyquota.Config{
		HarnessName:  "claude-tui",
		Binary:       "claude",
		Args:         nil,
		Workdir:      "",
		Env:          nil,
		Command:      "/status\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     anthropic.ClaudeAccountObservationComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		Discovery: func(text string) (cassette.DiscoveryRecord, error) {
			var err error
			obs, err = anthropic.ParseClaudeAccountObservation(text)
			if err != nil {
				return cassette.DiscoveryRecord{}, err
			}
			return cassette.DiscoveryRecord{
				Source:            "pty",
				Status:            string(ptyquota.StatusOK),
				CapturedAt:        now.UTC().Format(time.RFC3339),
				FreshnessWindow:   (24 * time.Hour).String(),
				StalenessBehavior: "stale status evidence requires authenticated PTY refresh before capability promotion",
				Metadata:          map[string]any{"detail": obs.Detail},
			}, nil
		},
	})
	if err != nil {
		return anthropic.ClaudeAccountObservation{}, err
	}
	return obs, nil
}

func readClaudeTuiQuotaViaPTY(ctx context.Context, now time.Time) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	timeout := 30 * time.Second
	if deadline, ok := ctx.Deadline(); ok {
		if remaining := time.Until(deadline); remaining > 0 && remaining < timeout {
			timeout = remaining
		}
	}
	var windows []harnesses.QuotaWindow
	var account *harnesses.AccountInfo
	_, err := ptyquota.Run(ctx, ptyquota.Config{
		HarnessName:  "claude-tui",
		Binary:       "claude",
		Args:         nil,
		Workdir:      "",
		Env:          nil,
		Command:      "/usage\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     anthropic.ClaudeQuotaObservationComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		Quota: func(text string) (cassette.QuotaRecord, error) {
			var parseErr error
			windows, account, parseErr = anthropic.ParseClaudeQuotaObservation(text)
			if parseErr != nil {
				return cassette.QuotaRecord{}, parseErr
			}
			return cassette.QuotaRecord{
				Source:            "pty",
				Status:            string(ptyquota.StatusOK),
				CapturedAt:        now.UTC().Format(time.RFC3339),
				FreshnessWindow:   (15 * time.Minute).String(),
				StalenessBehavior: "stale quota evidence keeps claude-tui out of automatic routing and is treated as limited",
				AccountClass:      anthropic.NormalizeClaudePlanType(accountPlan(account)),
				Metadata:          map[string]any{"detail": windows},
			}, nil
		},
	})
	if err != nil {
		return nil, nil, err
	}
	return windows, account, nil
}

func claudeTuiAccountSnapshotFromObservation(obs anthropic.ClaudeAccountObservation, now time.Time) harnesses.AccountSnapshot {
	snap := harnesses.AccountSnapshot{
		Authenticated:   obs.Authenticated,
		Unauthenticated: obs.Unauthenticated,
		Source:          "pty",
		CapturedAt:      now.UTC(),
		Fresh:           true,
		Detail:          obs.Detail,
	}
	if obs.Account != nil {
		snap.Email = obs.Account.Email
		snap.PlanType = obs.Account.PlanType
		snap.OrgName = obs.Account.OrgName
	}
	if snap.Authenticated && !snap.Unauthenticated && obs.Account == nil {
		snap.Detail = strings.TrimSpace(snap.Detail)
	}
	return snap
}

func claudeTuiQuotaStatusFromObservation(windows []harnesses.QuotaWindow, account *harnesses.AccountInfo, now time.Time) harnesses.QuotaStatus {
	status := harnesses.QuotaStatus{
		Source:            "pty",
		CapturedAt:        now.UTC(),
		Fresh:             true,
		Age:               0,
		State:             harnesses.QuotaOK,
		Windows:           append([]harnesses.QuotaWindow(nil), windows...),
		RoutingPreference: harnesses.RoutingPreferenceAvailable,
		Reason:            "live /usage snapshot from claude-tui",
	}
	if account != nil {
		status.Account = &harnesses.AccountSnapshot{
			Authenticated:   true,
			Source:          "pty",
			CapturedAt:      now.UTC(),
			Fresh:           true,
			PlanType:        account.PlanType,
			Email:           account.Email,
			OrgName:         account.OrgName,
			Unauthenticated: false,
		}
	}
	for _, window := range windows {
		if window.State == "blocked" {
			status.State = harnesses.QuotaBlocked
			status.RoutingPreference = harnesses.RoutingPreferenceBlocked
			status.Reason = "live /usage snapshot reports blocked quota"
			break
		}
	}
	return status
}

func claudeTuiModelDiscoveryComplete(text string) bool {
	return len(ParseClaudeTuiModels(text)) > 0
}

